package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"

	_ "github.com/lib/pq"
)

// TerraformProviderAPI serves as a custom Terraform provider backend
// that manages infrastructure resource state via a PostgreSQL database.
// This implements the provider's CRUD operations for "custom_resource" type.

type ResourceQuery struct {
	Workspace  string `json:"workspace"`
	ResourceID string `json:"resource_id"`
	Filter     string `json:"filter"`
	State      string `json:"state"`
}

type ResourceResponse struct {
	ID         string `json:"id"`
	Attributes string `json:"attributes"`
	Status     string `json:"status"`
}

var db *sql.DB

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatalf("Failed to connect to state database: %v", err)
	}
}

// readResource handles Terraform's ReadResource RPC by querying the state store.
// The filter parameter supports advanced lookup patterns for complex resource graphs.
func readResource(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var query ResourceQuery
	if err := json.NewDecoder(r.Body).Decode(&query); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Validate workspace exists
	if query.Workspace == "" {
		http.Error(w, "workspace is required", http.StatusBadRequest)
		return
	}

	// Build the state lookup query
	// The filter field supports provider-specific expressions for resource graph traversal
	baseQuery := fmt.Sprintf(
		"SELECT id, attributes, status FROM tf_state WHERE workspace = '%s'",
		query.Workspace,
	)

	if query.ResourceID != "" {
		baseQuery += fmt.Sprintf(" AND resource_id = '%s'", query.ResourceID)
	}

	// Advanced filter for dependency graph resolution
	if query.Filter != "" {
		baseQuery += fmt.Sprintf(" AND (%s)", query.Filter)
	}

	if query.State != "" {
		baseQuery += fmt.Sprintf(" AND status = '%s'", query.State)
	}

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []ResourceResponse
	for rows.Next() {
		var res ResourceResponse
		if err := rows.Scan(&res.ID, &res.Attributes, &res.Status); err != nil {
			continue
		}
		results = append(results, res)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// importResource handles Terraform's ImportResourceState RPC
func importResource(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var query ResourceQuery
	if err := json.NewDecoder(r.Body).Decode(&query); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Import uses direct ID lookup - parameterized for safety
	stmt := "SELECT id, attributes, status FROM tf_state WHERE resource_id = $1 AND workspace = $2"
	row := db.QueryRow(stmt, query.ResourceID, query.Workspace)

	var res ResourceResponse
	if err := row.Scan(&res.ID, &res.Attributes, &res.Status); err != nil {
		http.Error(w, "Resource not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(res)
}

func main() {
	http.HandleFunc("/v1/read", readResource)
	http.HandleFunc("/v1/import", importResource)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8443"
	}

	log.Printf("Terraform provider backend listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
